import { useEffect, useMemo, useRef, useState } from 'react'
import type * as React from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import {
  Archive, ArrowLeft, ArrowRight, Bell, BookOpen, Check, CheckCircle2, ChevronDown, Clipboard, ClipboardCheck,
  Clock3, Copy, Download, ExternalLink, FileJson, Filter, FolderKanban, Gauge, Inbox, LayoutDashboard, Link2,
  ListChecks, MessageSquare, MoreHorizontal, Plus, RefreshCw, Search, Send, Settings2, ShieldAlert, Sparkles, EyeOff, SlidersHorizontal,
  Target, Trash2, Upload, UserRound, WandSparkles, X, Zap, GitBranch, Layers3,
} from 'lucide-react'
import { buildJiraLink, defaultBugFix, defaultCreativeBrief, defaultHookup, defaultOptimization, defaultReflection, defaultResearch, defaultRequirements, defaultSubmission, defaultSubmissionChecklist, defaultTestingChecklist, initialData, makeId, migrateAppData, nowIso } from './dataMode'
import type { AppData, BugFixDetails, ChecklistItem, Discipline, EffectType, FeedbackRequest, FeedbackStatus, FollowUp, FollowUpStatus, HistoryEntry, HookupDetails, MessageFormat, MessageTone, MessageType, NoteType, OptimizationDetails, PipelineCard, Priority, PromotedLesson, Reflection, RelationType, RequirementBreakdown, ResearchDetails, SavedView, Stage, Task, TaskDetailPreferences, TaskFamily, TaskLifecycle, TaskPageDensity, TaskRelationship, TaskTemplate, TaskUIState, VariationDecision, WorkCategory, WorkLog, WorkType } from './types'
import { EFFECT_TAGS, EFFECT_TYPES, IMPACT_TAGS, MISSING_INFO, NOTE_TYPES, REFLECTION_TAGS, RELATION_TYPES, REQUIRED_STATES, STAGES, WORK_TYPES } from './types'
import { FamiliesPage, PipelinesPage, RelatedTaskDialog, RelatedWorkDrawer, ReflectionPromotionBar, TaskContextBar, type RelatedTaskDraft } from './related'
import { buildChangelistDescription, buildClarificationMessage, buildFeedbackMessage, buildMessage, cn, dueLabel, formatDate, formatRelative, impactReminders, initials, searchTask, stageClass } from './utils'
import ProgressiveOverview from './ProgressiveOverview'
import OfflineUpdatePrompt from './OfflineUpdatePrompt'
import { APP_MODE } from './appMode'
import './styles.css'

const STORAGE_KEY = APP_MODE.storageKey
const APP_VERSION = '0.1.0'
const DISCIPLINES: Discipline[] = ['Design', 'Tech Design', 'Art', 'Audio', 'Production', 'Nobody']
const PRIORITIES: Priority[] = ['Critical', 'High', 'Normal', 'Low']
const WORK_CATEGORIES: WorkCategory[] = ['Setup', 'Blockout', 'Simulation', 'Material', 'Particle work', 'Hookup', 'Scriptable work', 'Optimization', 'Bug fixing', 'Testing', 'Polish', 'Documentation']
const FEEDBACK_STATUSES: FeedbackStatus[] = ['Draft', 'Sent', 'Waiting', 'Received', 'Resolved', 'No longer needed']
const FOLLOW_UP_STATUSES: FollowUpStatus[] = ['Open', 'In progress', 'Done']
const MESSAGE_TYPES: MessageType[] = ['Clarification request', 'First-pass update', 'Feedback request', 'Progress update', 'Blocker update', 'Ready-for-review update', 'Changelist submitted', 'Verification request', 'Bug reproduction update', 'Unable-to-reproduce update', 'SFX notification', 'Final completion update']
const TONES: MessageTone[] = ['Friendly and casual', 'Neutral', 'Concise', 'More detailed']
const FORMATS: MessageFormat[] = ['Slack', 'Jira comment', 'Stand-up note']

type View = 'dashboard' | 'intake' | 'workspace' | 'templates' | 'library' | 'all-tasks' | 'families' | 'pipelines'
type WorkspaceTab = 'Overview' | 'Work Log' | 'Feedback' | 'Testing' | 'Submission' | 'Messages' | 'Reflection' | 'History'

const routePath = (view: View, taskId?: string, tab?: WorkspaceTab) => view === 'workspace' && taskId ? `/workspace/${encodeURIComponent(taskId)}/${encodeURIComponent(tab ?? 'Overview')}` : `/${view}`
const parseRoute = (pathname: string): { view: View; taskId?: string; tab?: WorkspaceTab } => {
  const parts = pathname.replace(/^\/+/, '').split('/').filter(Boolean).map((part) => decodeURIComponent(part))
  const view = parts[0] as View
  if (view === 'workspace') {
    const validTabs: WorkspaceTab[] = ['Overview', 'Work Log', 'Feedback', 'Testing', 'Submission', 'Messages', 'Reflection', 'History']
    return { view, taskId: parts[1], tab: validTabs.includes(parts[2] as WorkspaceTab) ? parts[2] as WorkspaceTab : 'Overview' }
  }
  return { view: ['dashboard', 'intake', 'templates', 'library', 'all-tasks', 'families', 'pipelines'].includes(view) ? view : 'dashboard' }
}

interface IntakeDraft {
  name: string
  feature: string
  mapMode: string
  jira: string
  source: string
  requestingDiscipline: string
  requester: string
  priority: Priority
  workType: WorkType
  effectType: EffectType
  tags: string[]
  stage: Stage
  nextAction: string
  targetDate: string
  rawRequest: string
  requirements: RequirementBreakdown
  pipelineId: string
}

const createIntakeDraft = (): IntakeDraft => ({
  name: '', feature: '', mapMode: '', jira: '', source: 'Slack', requestingDiscipline: 'Design', requester: '', priority: 'Normal', workType: 'New VFX', effectType: 'Other', tags: [], stage: 'New Request', nextAction: '', targetDate: '', rawRequest: '', requirements: defaultRequirements(), pipelineId: '',
})

const cloneData = (data: AppData): AppData => JSON.parse(JSON.stringify(data)) as AppData

function App() {
  const location = useLocation()
  const navigate = useNavigate()
  const [data, setData] = useState<AppData>(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY)
      return migrateAppData(stored ? JSON.parse(stored) : initialData)
    } catch {
      return initialData
    }
  })
  const [view, setView] = useState<View>('dashboard')
  const [selectedTaskId, setSelectedTaskId] = useState(initialData.tasks[0].id)
  const [activeTab, setActiveTab] = useState<WorkspaceTab>('Overview')
  const [search, setSearch] = useState('')
  const [toast, setToast] = useState('')
  const [filterStatus, setFilterStatus] = useState('All status')
  const [filterPriority, setFilterPriority] = useState('All priorities')
  const [filterFeature, setFilterFeature] = useState('All features')
  const [filterWaiting, setFilterWaiting] = useState('All blockers')
  const [filterMap, setFilterMap] = useState('All maps')
  const [filterEffect, setFilterEffect] = useState('All effect types')
  const [filterTag, setFilterTag] = useState('All tags')
  const [filterFeedback, setFilterFeedback] = useState('All feedback')
  const [filterChangelist, setFilterChangelist] = useState('All changelists')
  const [filterReflection, setFilterReflection] = useState('All reflections')
  const [filterCompletion, setFilterCompletion] = useState('Active and completed')
  const [showAdvancedFilters, setShowAdvancedFilters] = useState(false)
  const [intake, setIntake] = useState<IntakeDraft>(() => createIntakeDraft())
  const [newLogOpen, setNewLogOpen] = useState(true)
  const [logDraft, setLogDraft] = useState<Partial<WorkLog>>({ category: 'Change', at: nowIso(), changed: '', remains: '', issue: '', link: '', changelist: '' })
  const [newFeedbackOpen, setNewFeedbackOpen] = useState(false)
  const [feedbackDraft, setFeedbackDraft] = useState<Partial<FeedbackRequest>>({ requestedFrom: '', discipline: 'Design', dateRequested: new Date().toISOString().slice(0, 10), build: '', previewLink: '', changed: '', question: 'Does the gameplay timing read correctly?', status: 'Draft', response: '', decision: '', followUp: '' })
  const [messageType, setMessageType] = useState<MessageType>('Progress update')
  const [messageTone, setMessageTone] = useState<MessageTone>('Neutral')
  const [messageFormat, setMessageFormat] = useState<MessageFormat>('Slack')
  const [messageOutput, setMessageOutput] = useState('')
  const [templateId, setTemplateId] = useState(initialData.templates[0].id)
  const [templateDraft, setTemplateDraft] = useState<TaskTemplate>(initialData.templates[0])
  const [relatedDialogOpen, setRelatedDialogOpen] = useState(false)
  const [relatedPanelOpen, setRelatedPanelOpen] = useState(false)
  const [selectedFamilyId, setSelectedFamilyId] = useState('')
  const [selectedPipelineId, setSelectedPipelineId] = useState('')
  const [online, setOnline] = useState(() => typeof navigator === 'undefined' ? true : navigator.onLine)
  const searchInputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    const route = parseRoute(location.pathname)
    setView(route.view)
    if (route.taskId) setSelectedTaskId(route.taskId)
    if (route.tab) setActiveTab(route.tab)
  }, [location.pathname])

  useEffect(() => {
    const updateOnline = () => setOnline(navigator.onLine)
    window.addEventListener('online', updateOnline)
    window.addEventListener('offline', updateOnline)
    return () => { window.removeEventListener('online', updateOnline); window.removeEventListener('offline', updateOnline) }
  }, [])

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data))
  }, [data])

  useEffect(() => {
    const archiveDays = data.preferences?.autoArchiveDays ?? 0
    if (!archiveDays) return
    const cutoff = Date.now() - archiveDays * 86400000
    setData((current) => {
      let changed = false
      const tasks = current.tasks.map((task) => {
        if (task.lifecycle === 'Completed' && !task.archivedAt && new Date(task.updatedAt).getTime() < cutoff) {
          changed = true
          const archivedAt = nowIso()
          return { ...task, lifecycle: 'Archived' as TaskLifecycle, archivedAt, updatedAt: archivedAt }
        }
        return task
      })
      return changed ? { ...current, tasks } : current
    })
  }, [data.preferences?.autoArchiveDays])

  useEffect(() => {
    if (!toast) return
    const timeout = window.setTimeout(() => setToast(''), 2600)
    return () => window.clearTimeout(timeout)
  }, [toast])

  const selectedTask = data.tasks.find((task) => task.id === selectedTaskId) ?? data.tasks[0]
  const taskPageDensity: TaskPageDensity = data.preferences?.taskPageDensity ?? 'Lean'
  const setTaskPageDensity = (density: TaskPageDensity) => setData((current) => ({ ...current, preferences: { ...(current.preferences ?? { autoArchiveDays: 0 }), taskPageDensity: density } }))
  const selectedTaskUIState: TaskUIState = selectedTask ? (data.taskViewState?.[selectedTask.id] ?? {}) : {}
  const updateTaskUIState = (taskId: string, patch: Partial<TaskUIState>) => setData((current) => ({ ...current, taskViewState: { ...(current.taskViewState ?? {}), [taskId]: { ...(current.taskViewState?.[taskId] ?? {}), ...patch } } }))
  const filteredTasks = useMemo(() => data.tasks.filter((task) => {
    if (!searchTask(task, search)) return false
    if (filterStatus !== 'All status' && task.stage !== filterStatus) return false
    if (filterPriority !== 'All priorities' && task.priority !== filterPriority) return false
    if (filterFeature !== 'All features' && task.feature !== filterFeature) return false
    if (filterWaiting !== 'All blockers' && (task.requirements.missingInfo.length || task.blocker ? task.requestingDiscipline : 'Nobody') !== filterWaiting) return false
    if (filterMap !== 'All maps' && task.mapMode !== filterMap) return false
    if (filterEffect !== 'All effect types' && task.effectType !== filterEffect) return false
    if (filterTag !== 'All tags' && !task.tags.includes(filterTag)) return false
    if (filterFeedback === 'Unresolved feedback' && !task.feedback.some((item) => !['Resolved', 'No longer needed'].includes(item.status))) return false
    if (filterFeedback === 'No unresolved feedback' && task.feedback.some((item) => !['Resolved', 'No longer needed'].includes(item.status))) return false
    if (filterChangelist === 'Has changelist' && !task.submission.changelist) return false
    if (filterChangelist === 'No changelist' && task.submission.changelist) return false
    if (filterReflection === 'Has reflection' && !task.reflection.completed) return false
    if (filterReflection === 'No reflection' && task.reflection.completed) return false
    if (filterCompletion === 'Active only' && task.lifecycle !== 'Active') return false
    if (filterCompletion === 'Completed only' && task.lifecycle !== 'Completed') return false
    if (filterCompletion === 'Archived only' && task.lifecycle !== 'Archived') return false
    if (filterCompletion === 'Active and completed' && task.lifecycle === 'Archived') return false
    return true
  }), [data.tasks, filterCompletion, filterEffect, filterFeedback, filterFeature, filterMap, filterPriority, filterReflection, filterStatus, filterTag, filterWaiting, filterChangelist, search])

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') {
        event.preventDefault()
        searchInputRef.current?.focus()
      }
      if (event.key === 'Escape') setSearch('')
    }
    window.addEventListener('keydown', onKeyDown)
    const onPointerDown = (event: PointerEvent) => {
      const target = event.target as HTMLElement
      if (!target.closest('.search-box') && !target.closest('.search-results')) setSearch('')
    }
    window.addEventListener('pointerdown', onPointerDown)
    return () => { window.removeEventListener('keydown', onKeyDown); window.removeEventListener('pointerdown', onPointerDown) }
  }, [])

  const updateTask = (id: string, updater: (task: Task) => Task) => {
    setData((current) => ({ ...current, tasks: current.tasks.map((task) => task.id === id ? updater(task) : task) }))
  }

  const patchTask = (patch: Partial<Task>) => {
    if (!selectedTask) return
    updateTask(selectedTask.id, (task) => ({ ...task, ...patch, updatedAt: nowIso() }))
  }

  const addHistory = (task: Task, entry: Omit<HistoryEntry, 'id' | 'at'>): Task => ({ ...task, updatedAt: nowIso(), history: [{ ...entry, id: makeId('history'), at: nowIso() }, ...task.history] })

  const setTaskStage = (stage: Stage) => {
    if (!selectedTask || selectedTask.stage === stage) return
    updateTask(selectedTask.id, (task) => addHistory({ ...task, stage, lifecycle: stage === 'Complete' ? 'Completed' : task.lifecycle === 'Archived' ? 'Archived' : 'Active', updatedAt: nowIso() }, { type: 'Status', label: `Moved to ${stage}`, detail: `Stage changed from ${task.stage}.` }))
    if (stage === 'Complete') {
      setActiveTab('Reflection')
      setToast('Task complete — add an optional reflection')
      return
    }
    setToast(`Moved ${selectedTask.name} to ${stage}`)
  }

  const openTask = (id: string, tab: WorkspaceTab = 'Overview') => {
    setSelectedTaskId(id)
    setActiveTab(tab)
    setView('workspace')
    navigate(routePath('workspace', id, tab))
    setData((current) => ({
      ...current,
      recentTaskIds: [id, ...(current.recentTaskIds ?? []).filter((taskId) => taskId !== id)].slice(0, 12),
      tasks: current.tasks.map((task) => task.id === id ? { ...task, lastOpenedAt: nowIso() } : task),
    }))
  }

  const togglePinned = (id: string) => {
    setData((current) => {
      const pinnedIds = current.pinnedTaskIds ?? current.tasks.filter((task) => task.pinned).map((task) => task.id)
      const isPinned = pinnedIds.includes(id)
      if (!isPinned && pinnedIds.length >= 5) {
        setToast('Pinned is limited to five tasks')
        return current
      }
      return { ...current, pinnedTaskIds: isPinned ? pinnedIds.filter((taskId) => taskId !== id) : [...pinnedIds, id], tasks: current.tasks.map((task) => task.id === id ? { ...task, pinned: !isPinned, updatedAt: nowIso() } : task) }
    })
  }

  const archiveTask = (id: string) => {
    updateTask(id, (task) => addHistory({ ...task, lifecycle: 'Archived', archivedAt: nowIso() }, { type: 'Status', label: 'Archived task', detail: 'Task moved out of active views but remains searchable and restorable.' }))
    setToast('Task archived')
  }

  const restoreTask = (id: string) => {
    updateTask(id, (task) => addHistory({ ...task, lifecycle: task.stage === 'Complete' ? 'Completed' : 'Active', archivedAt: '' }, { type: 'Status', label: 'Restored task', detail: 'Task returned from archive.' }))
    setToast('Task restored')
  }

  const copyText = async (text: string, label = 'Copied to clipboard') => {
    try {
      await navigator.clipboard.writeText(text)
      setToast(label)
    } catch {
      setToast('Copy is unavailable in this browser context')
    }
  }

  const toggleFocus = (id: string) => {
    setData((current) => {
      const isFocused = current.focusTaskIds.includes(id)
      if (!isFocused && current.focusTaskIds.length >= 3) {
        setToast('Today Focus is limited to three tasks')
        return current
      }
      return { ...current, focusTaskIds: isFocused ? current.focusTaskIds.filter((taskId) => taskId !== id) : [...current.focusTaskIds, id] }
    })
  }

  const createTask = () => {
    if (!intake.name.trim()) {
      setToast('Add a task name before creating the request')
      return
    }
    const timestamp = nowIso()
    const missing = intake.requirements.missingInfo
    const task: Task = {
      creativeBrief: defaultCreativeBrief(),
      bugFix: defaultBugFix(),
      optimization: defaultOptimization(),
      hookup: defaultHookup(),
      research: defaultResearch(),
      reflection: defaultReflection(),
      id: makeId('task'), name: intake.name.trim(), feature: intake.feature, mapMode: intake.mapMode, jira: intake.jira, source: intake.source, requestingDiscipline: intake.requestingDiscipline, requester: intake.requester, priority: intake.priority, workType: intake.workType, effectType: intake.effectType, tags: intake.tags, lifecycle: 'Active', pinned: false, lastOpenedAt: timestamp, archivedAt: '', familyId: '', relationships: [], pipelineIds: intake.pipelineId ? [intake.pipelineId] : [], leanCanvas: {}, detailPreferences: { visibleSections: [], hiddenSections: [], collapsedSections: [], order: [] }, targetDate: intake.targetDate, rawRequest: intake.rawRequest,
      requirements: intake.requirements, stage: missing.length ? 'Needs Clarification' : 'New Request', visualDirection: '', nextAction: missing.length ? 'Send the clarification note and resolve the open requirements.' : 'Review the request and define the first pass.', blocker: missing.length ? `${missing.length} requirement${missing.length === 1 ? '' : 's'} need clarification.` : '', people: intake.requester ? [`${intake.requester} · ${intake.requestingDiscipline}`] : [], links: intake.jira ? [buildJiraLink(intake.jira)] : [], keyRequirements: [], openQuestions: missing, latestFeedback: '', latestChangelist: '', createdAt: timestamp, updatedAt: timestamp, workLogs: [], feedback: [], testing: defaultTestingChecklist(), testingInstructions: { consoleCommand: '', mapLocation: '', triggerMethod: '', requiredWeapon: '', gameplaySetup: '', knownIssue: '' }, submission: defaultSubmission({ relatedJira: intake.jira }), impactTags: [], followUps: [], history: [{ id: makeId('history'), at: timestamp, type: 'Status', label: `Created in ${missing.length ? 'Needs Clarification' : 'New Request'}`, detail: 'Request captured from intake form.' }],
    }
    const adjustedTask: Task = { ...task, stage: intake.stage === 'New Request' && missing.length ? 'Needs Clarification' : intake.stage, nextAction: intake.nextAction || task.nextAction }
    setData((current) => ({ ...current, tasks: [adjustedTask, ...current.tasks] }))
    setSelectedTaskId(adjustedTask.id)
    setView('workspace')
    setActiveTab('Overview')
    navigate(routePath('workspace', adjustedTask.id, 'Overview'))
    setIntake(createIntakeDraft())
    setToast('Task created')
  }

  const exportData = () => {
    const payload = { exportDate: nowIso(), applicationVersion: APP_VERSION, schemaVersion: 1, ...data }
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const anchor = document.createElement('a')
    anchor.href = url
    anchor.download = `vfx-workflow-backup-${new Date().toISOString().slice(0, 10)}.json`
    anchor.click()
    URL.revokeObjectURL(url)
    setToast(APP_MODE.publicDemo ? 'Public demo export created — keep sensitive data out' : 'Local workspace exported')
  }

  const importData = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = () => {
      try {
        const imported = migrateAppData(JSON.parse(String(reader.result)))
        if (!Array.isArray(imported.tasks) || !Array.isArray(imported.templates)) throw new Error('Invalid backup')
        const choice = window.prompt('Import this backup: type MERGE, REPLACE, or CANCEL.')?.trim().toUpperCase()
        if (choice === 'CANCEL' || !choice) return
        if (choice === 'REPLACE') {
          localStorage.setItem(`${STORAGE_KEY}.backup`, JSON.stringify({ exportDate: nowIso(), applicationVersion: APP_VERSION, schemaVersion: 1, ...data }))
          setData(imported)
        } else if (choice === 'MERGE') {
          const merge = <T extends { id: string }>(current: T[], next: T[]) => [...current, ...next.filter((item) => !current.some((existing) => existing.id === item.id))]
          setData((current) => ({ ...current, tasks: merge(current.tasks, imported.tasks), templates: merge(current.templates, imported.templates), families: merge(current.families ?? [], imported.families ?? []), pipelines: merge(current.pipelines ?? [], imported.pipelines ?? []), savedViews: merge(current.savedViews ?? [], imported.savedViews ?? []), promotedLessons: merge(current.promotedLessons ?? [], imported.promotedLessons ?? []) }))
        } else throw new Error('Invalid import choice')
        setSelectedTaskId(imported.tasks[0]?.id ?? '')
        setToast(choice === 'MERGE' ? 'Workspace merged' : 'Workspace replaced; local backup created')
      } catch {
        setToast('That file is not a valid workflow backup')
      }
    }
    reader.readAsText(file)
    event.target.value = ''
  }

  const addWorkLog = () => {
    if (!selectedTask || !logDraft.changed?.trim()) {
      setToast('Add what changed before saving the work log')
      return
    }
    const prefix = /^(\/(change|issue|test|feedback|decision|todo|cl|learning|reference))\s+/i.exec(logDraft.changed.trim())
    const categoryMap: Record<string, WorkLog['category']> = { change: 'Change', issue: 'Issue', test: 'Test', feedback: 'Feedback', decision: 'Decision', todo: 'Todo', cl: 'CL', learning: 'Learning', reference: 'Reference' }
    const prefixKey = prefix?.[2]?.toLowerCase()
    const log: WorkLog = { id: makeId('log'), at: nowIso(), category: (prefixKey ? categoryMap[prefixKey] : logDraft.category as WorkLog['category']) || 'Change', changed: prefix ? logDraft.changed.trim().slice(prefix[0].length) : logDraft.changed || '', remains: logDraft.remains || '', issue: logDraft.issue || '', link: logDraft.link || '', changelist: logDraft.changelist || '' }
    updateTask(selectedTask.id, (task) => addHistory({ ...task, workLogs: [log, ...task.workLogs] }, { type: 'Work log', label: `Logged ${log.category.toLowerCase()} work`, detail: log.changed }))
    setLogDraft({ category: 'Change', at: nowIso(), changed: '', remains: '', issue: '', link: '', changelist: '' })
    setNewLogOpen(false)
    setToast('Work log added')
  }

  const promoteNote = (taskId: string, noteId: string, target: 'Next action' | 'Main blocker' | 'Current finding' | 'Test result' | 'Feedback decision' | 'Submission summary' | 'Reflection lesson') => {
    updateTask(taskId, (task) => {
      const note = task.workLogs.find((item) => item.id === noteId)
      if (!note) return task
      const text = note.changed.trim()
      const next: Task = { ...task }
      if (target === 'Next action') next.nextAction = text
      if (target === 'Main blocker') next.blocker = text
      if (target === 'Current finding') next.leanCanvas = { ...(task.leanCanvas ?? {}), currentFinding: text }
      if (target === 'Test result') next.leanCanvas = { ...(task.leanCanvas ?? {}), testResult: text }
      if (target === 'Feedback decision') next.latestFeedback = text
      if (target === 'Submission summary') next.submission = { ...task.submission, description: text }
      if (target === 'Reflection lesson') next.reflection = { ...task.reflection, reusable: text }
      return addHistory(next, { type: 'Decision', label: `Promoted note to ${target}`, detail: text })
    })
    setToast(`Note promoted to ${target}`)
  }

  const addFeedback = () => {
    if (!selectedTask || !feedbackDraft.question?.trim()) {
      setToast('Add a focused feedback question before saving')
      return
    }
    const feedback: FeedbackRequest = { id: makeId('feedback'), requestedFrom: feedbackDraft.requestedFrom || '', discipline: feedbackDraft.discipline || 'Design', dateRequested: feedbackDraft.dateRequested || new Date().toISOString().slice(0, 10), build: feedbackDraft.build || '', previewLink: feedbackDraft.previewLink || '', changed: feedbackDraft.changed || '', question: feedbackDraft.question || '', status: feedbackDraft.status as FeedbackStatus || 'Draft', response: feedbackDraft.response || '', decision: feedbackDraft.decision || '', followUp: feedbackDraft.followUp || '' }
    updateTask(selectedTask.id, (task) => addHistory({ ...task, feedback: [feedback, ...task.feedback], latestFeedback: feedback.response || feedback.question }, { type: 'Feedback', label: `Feedback ${feedback.status.toLowerCase()}`, detail: feedback.question }))
    setFeedbackDraft({ requestedFrom: '', discipline: 'Design', dateRequested: new Date().toISOString().slice(0, 10), build: '', previewLink: '', changed: '', question: 'Does the gameplay timing read correctly?', status: 'Draft', response: '', decision: '', followUp: '' })
    setNewFeedbackOpen(false)
    setToast('Feedback request added')
  }

  const addFollowUp = () => {
    if (!selectedTask) return
    const follow: FollowUp = { id: makeId('follow'), owner: 'Unassigned', createdAt: new Date().toISOString().slice(0, 10), nextAction: 'Define next action', status: 'Open', reminderDate: '', kind: 'General follow-up' }
    updateTask(selectedTask.id, (task) => addHistory({ ...task, followUps: [follow, ...task.followUps] }, { type: 'Follow-up', label: 'Added follow-up', detail: follow.kind }))
    setActiveTab('Overview')
    setToast('Follow-up added')
  }

  const resetAllData = () => {
    if (!window.confirm('Reset the local workspace to the sample data?')) return
    setData(cloneData(initialData))
    setSelectedTaskId(initialData.tasks[0].id)
    setView('dashboard')
    navigate(routePath('dashboard'))
    setToast('Sample workspace restored')
  }

  const nav = (nextView: View) => {
    setView(nextView)
    if (nextView === 'workspace' && !selectedTask) setView('dashboard')
    navigate(routePath(nextView, nextView === 'workspace' ? selectedTask?.id : undefined, nextView === 'workspace' ? activeTab : undefined))
  }

  const setWorkspaceTab = (tab: WorkspaceTab) => {
    setActiveTab(tab)
    if (selectedTask) navigate(routePath('workspace', selectedTask.id, tab))
  }

  const useStartingPoint = (template: TaskTemplate) => {
    const inferredWorkType = template.workType ?? (template.name.toLowerCase().includes('bug') ? 'Bug Fix' : template.name.toLowerCase().includes('optimization') ? 'Optimization' : template.name.toLowerCase().includes('hookup') ? 'Hookup / Integration' : 'New VFX')
    const inferredEffect = template.effectType ?? (template.name.toLowerCase().includes('portal') ? 'Portal' : template.name.toLowerCase().includes('charge') ? 'Charge-up' : template.name.toLowerCase().includes('environment') ? 'Environment' : 'Other')
    setIntake((current) => ({ ...current, workType: inferredWorkType, effectType: inferredEffect, pipelineId: template.pipelineId ?? current.pipelineId, tags: Array.from(new Set([...current.tags, ...(template.commonTags ?? template.impactTags ?? [])])) }))
    nav('intake')
    setToast(`${template.name} starting point loaded`)
  }

  const openFamily = (id: string) => { setSelectedFamilyId(id); nav('families') }
  const openPipeline = (id: string) => { setSelectedPipelineId(id); nav('pipelines') }

  const createRelatedTask = (draft: RelatedTaskDraft) => {
    if (!selectedTask || !draft.name.trim()) return
    const timestamp = nowIso()
    const source = selectedTask
    const inherit = draft.inherit
    const requirements = defaultRequirements({
      ...(inherit.map ? source.requirements : {}),
      existingReference: inherit.references ? source.requirements.existingReference : '',
      technicalConstraints: inherit.technical ? source.requirements.technicalConstraints : '',
      dependencies: inherit.dependencies ? source.requirements.dependencies : '',
      missingInfo: [],
    })
    const relatedId = makeId('task')
    const relation: TaskRelationship = { id: makeId('relation'), sourceTaskId: relatedId, targetTaskId: source.id, relationType: draft.relationType, note: draft.note.trim(), createdAt: timestamp }
    const relatedTask: Task = {
      ...source,
      id: relatedId,
      name: draft.name.trim(),
      jira: '',
      source: 'Related task',
      requester: '',
      priority: 'Normal',
      workType: draft.workType,
      effectType: inherit.effect && draft.effectType ? draft.effectType : 'Other',
      tags: inherit.tags ? [...source.tags] : [],
      lifecycle: 'Active',
      pinned: false,
      lastOpenedAt: timestamp,
      archivedAt: '',
      familyId: draft.familyId,
      relationships: [relation],
      pipelineIds: inherit.pipeline ? [...(source.pipelineIds ?? [])] : [],
      variationDecision: draft.relationType === 'Variation of' ? 'Exploring' : undefined,
      targetDate: '',
      rawRequest: draft.note.trim() ? `Related to ${source.name}. ${draft.note.trim()}` : `Related to ${source.name}. Define the focused scope for this ${draft.relationType.toLowerCase()}.`,
      requirements,
      stage: 'New Request',
      visualDirection: '',
      nextAction: 'Review inherited context and define the first pass.',
      blocker: '',
      people: [],
      links: inherit.assets || inherit.references ? [...source.links] : [],
      keyRequirements: [],
      openQuestions: [],
      latestFeedback: '',
      latestChangelist: '',
      createdAt: timestamp,
      updatedAt: timestamp,
      workLogs: [],
      feedback: [],
      testing: defaultTestingChecklist(),
      testingInstructions: inherit.testing ? { ...source.testingInstructions } : { consoleCommand: '', mapLocation: '', triggerMethod: '', requiredWeapon: '', gameplaySetup: '', knownIssue: '' },
      submission: defaultSubmission(),
      impactTags: [],
      followUps: [],
      reflection: defaultReflection(),
      creativeBrief: defaultCreativeBrief(),
      bugFix: defaultBugFix(),
      optimization: defaultOptimization(),
      hookup: defaultHookup(),
      research: defaultResearch(),
      leanCanvas: {},
      detailPreferences: { visibleSections: [], hiddenSections: [], collapsedSections: [], order: [] },
      history: [{ id: makeId('history'), at: timestamp, type: 'Status', label: 'Created as related task', detail: `Created from ${source.name} · ${draft.relationType}.` }],
    }
    setData((current) => ({
      ...current,
      tasks: [relatedTask, ...current.tasks],
      pipelines: (current.pipelines ?? []).map((pipeline) => relatedTask.pipelineIds.includes(pipeline.id) ? { ...pipeline, relatedTaskIds: Array.from(new Set([...pipeline.relatedTaskIds, relatedId])), updatedAt: timestamp } : pipeline),
      families: (current.families ?? []).map((family) => family.id === relatedTask.familyId ? { ...family, updatedAt: timestamp } : family),
    }))
    setSelectedTaskId(relatedId)
    setActiveTab('Overview')
    setRelatedDialogOpen(false)
    setRelatedPanelOpen(false)
    setView('workspace')
    setToast('Related task created')
  }

  const removeRelationship = (taskId: string, relationshipId: string) => {
    setData((current) => ({ ...current, tasks: current.tasks.map((task) => task.id === taskId ? { ...task, relationships: task.relationships.filter((relationship) => relationship.id !== relationshipId), updatedAt: nowIso() } : task) }))
    setToast('Relationship removed')
  }

  const linkExistingTask = (targetId: string, relationType: RelationType, note: string) => {
    if (!selectedTask || targetId === selectedTask.id) return
    const timestamp = nowIso()
    const relationship: TaskRelationship = { id: makeId('relation'), sourceTaskId: selectedTask.id, targetTaskId: targetId, relationType, note: note.trim(), createdAt: timestamp }
    updateTask(selectedTask.id, (task) => ({ ...task, relationships: [...task.relationships, relationship], updatedAt: timestamp }))
    setToast('Existing task linked')
  }

  const moveTaskToFamily = (taskId: string, familyId: string) => {
    updateTask(taskId, (task) => ({ ...task, familyId, updatedAt: nowIso() }))
    setToast(familyId ? 'Task moved into family' : 'Task kept task-specific')
  }

  const updateVariationDecision = (taskId: string, decision: VariationDecision) => updateTask(taskId, (task) => ({ ...task, variationDecision: decision, updatedAt: nowIso() }))

  const updateFamilyContext = (action: 'copy' | 'update' | 'keep') => {
    if (!selectedTask) return
    const family = (data.families ?? []).find((item) => item.id === selectedTask.familyId)
    if (action === 'keep') { moveTaskToFamily(selectedTask.id, ''); return }
    if (!family) { setToast('Link this task to a family first'); return }
    if (action === 'copy') {
      patchTask({ tags: [...family.sharedTags], pipelineIds: [...new Set([...(selectedTask.pipelineIds ?? []), ...family.sharedPipelineLinks])], links: [...new Set([...selectedTask.links, ...family.sharedAssetLinks, ...family.sharedReferences])], requirements: defaultRequirements({ ...selectedTask.requirements, existingReference: family.sharedReferences.join(', '), dependencies: family.sharedDependencies }) })
      setToast('Family context copied to task')
      return
    }
    const timestamp = nowIso()
    setData((current) => ({ ...current, families: (current.families ?? []).map((item) => item.id === family.id ? { ...item, sharedTags: Array.from(new Set([...item.sharedTags, ...selectedTask.tags])), sharedAssetLinks: Array.from(new Set([...item.sharedAssetLinks, ...selectedTask.links])), sharedPipelineLinks: Array.from(new Set([...item.sharedPipelineLinks, ...(selectedTask.pipelineIds ?? [])])), updatedAt: timestamp } : item) }))
    setToast('Family context updated from task')
  }

  const promoteLesson = (scope: 'Family' | 'Pipeline', originalText: string, summary: string) => {
    if (!selectedTask) return
    const timestamp = nowIso()
    const lesson: PromotedLesson = { id: makeId('lesson'), scope, sourceTaskId: selectedTask.id, familyId: scope === 'Family' ? selectedTask.familyId || undefined : undefined, pipelineId: scope === 'Pipeline' ? selectedTask.pipelineIds?.[0] : undefined, at: timestamp, originalText, summary: summary || originalText.split('\n')[0], tags: selectedTask.tags }
    setData((current) => ({
      ...current,
      promotedLessons: [...(current.promotedLessons ?? []), lesson],
      families: scope === 'Family' ? (current.families ?? []).map((family) => family.id === selectedTask.familyId ? { ...family, reusableLessons: Array.from(new Set([...family.reusableLessons, lesson.summary])), updatedAt: timestamp } : family) : current.families,
      pipelines: scope === 'Pipeline' ? (current.pipelines ?? []).map((pipeline) => pipeline.id === selectedTask.pipelineIds?.[0] ? { ...pipeline, reusableLessons: Array.from(new Set([...pipeline.reusableLessons, lesson.summary])), updatedAt: timestamp } : pipeline) : current.pipelines,
    }))
    setToast(`${scope} lesson promoted`)
  }

  const useReflectionAsStartingPoint = () => {
    if (!selectedTask) return
    const reflectionText = [selectedTask.reflection.reusable, selectedTask.reflection.nextTime, selectedTask.reflection.reusableSetup].filter(Boolean).join(' ')
    setIntake({ ...createIntakeDraft(), name: `${selectedTask.name} follow-up`, feature: selectedTask.feature, mapMode: selectedTask.mapMode, workType: 'Iteration / Polish', effectType: selectedTask.effectType, tags: [...selectedTask.tags], rawRequest: reflectionText || `Use ${selectedTask.name} as the starting point for the next pass.`, pipelineId: selectedTask.pipelineIds?.[0] ?? '' })
    setView('intake')
    setToast('Reflection loaded into intake')
  }

  const createPipeline = () => {
    const name = window.prompt('Name this reusable pipeline')
    if (!name?.trim()) return
    const timestamp = nowIso()
    const pipeline: PipelineCard = { id: makeId('pipeline'), name: name.trim(), purpose: 'Reusable setup for related VFX work.', workTypes: [], effectTypes: [], requiredAssetsSystems: '', setupSteps: [], eventNames: [], commonControls: '', testingInstructions: '', knownLimitations: '', commonFailureCases: '', reusableNotes: '', reusableLessons: [], relatedTaskIds: [], tags: [], createdAt: timestamp, updatedAt: timestamp }
    setData((current) => ({ ...current, pipelines: [...(current.pipelines ?? []), pipeline] }))
    setSelectedPipelineId(pipeline.id)
    setToast('Pipeline card created')
  }

  const saveCurrentView = () => {
    const name = window.prompt('Name this filter view')
    if (!name?.trim()) return
    const filters = { filterMap, filterFeature, filterEffect, filterTag, filterStatus, filterPriority, filterWaiting, filterFeedback, filterChangelist, filterReflection, filterCompletion }
    setData((current) => ({ ...current, savedViews: [...(current.savedViews ?? []).filter((view) => view.name !== name.trim()), { id: makeId('view'), name: name.trim(), filters }] }))
    setToast(`Saved filter view: ${name.trim()}`)
  }

  const applyFilterValues = (filters: Record<string, string>) => {
    setFilterMap(filters.filterMap ?? 'All maps')
    setFilterFeature(filters.filterFeature ?? 'All features')
    setFilterEffect(filters.filterEffect ?? 'All effect types')
    setFilterTag(filters.filterTag ?? 'All tags')
    setFilterStatus(filters.filterStatus ?? 'All status')
    setFilterPriority(filters.filterPriority ?? 'All priorities')
    setFilterWaiting(filters.filterWaiting ?? 'All blockers')
    setFilterFeedback(filters.filterFeedback ?? 'All feedback')
    setFilterChangelist(filters.filterChangelist ?? 'All changelists')
    setFilterReflection(filters.filterReflection ?? 'All reflections')
    setFilterCompletion(filters.filterCompletion ?? 'Active and completed')
  }

  const loadSavedView = (savedView: SavedView) => {
    applyFilterValues(savedView.filters)
    setShowAdvancedFilters(true)
    setToast(`Loaded filter view: ${savedView.name}`)
  }

  const deleteSavedView = (id: string) => {
    setData((current) => ({ ...current, savedViews: (current.savedViews ?? []).filter((savedView) => savedView.id !== id) }))
    setToast('Saved view deleted')
  }

  const filterSnapshot = { filterMap, filterFeature, filterEffect, filterTag, filterStatus, filterPriority, filterWaiting, filterFeedback, filterChangelist, filterReflection, filterCompletion }
  useEffect(() => {
    const hasFilter = Object.entries(filterSnapshot).some(([key, value]) => value !== ({ filterMap: 'All maps', filterFeature: 'All features', filterEffect: 'All effect types', filterTag: 'All tags', filterStatus: 'All status', filterPriority: 'All priorities', filterWaiting: 'All blockers', filterFeedback: 'All feedback', filterChangelist: 'All changelists', filterReflection: 'All reflections', filterCompletion: 'Active and completed' } as Record<string, string>)[key])
    if (!hasFilter) return
    const signature = JSON.stringify(filterSnapshot)
    setData((current) => {
      const recent = current.recentFilters ?? []
      if (JSON.stringify(recent[0]) === signature) return current
      return { ...current, recentFilters: [filterSnapshot, ...recent.filter((item) => JSON.stringify(item) !== signature)].slice(0, 6) }
    })
  }, [filterChangelist, filterCompletion, filterEffect, filterFeedback, filterFeature, filterMap, filterPriority, filterReflection, filterStatus, filterTag, filterWaiting])

  return (
    <div className="app-shell">
      <Sidebar view={view} data={data} tasks={data.tasks} selectedTaskId={selectedTask?.id} onNavigate={nav} onOpenTask={openTask} onNewTask={() => { nav('intake'); setIntake(createIntakeDraft()) }} onLibrary={() => nav('library')} onTogglePinned={togglePinned} online={online} />
      <main className="main-shell">
        <Topbar search={search} setSearch={setSearch} searchRef={searchInputRef} onExport={exportData} onImport={importData} onNewTask={() => { nav('intake'); setIntake(createIntakeDraft()) }} />
        <ModeNotice online={online} />
        {search && <SearchResults tasks={data.tasks} data={data} query={search} onOpen={(id, tab) => { setSearch(''); openTask(id, tab) }} />}
        {view === 'dashboard' && <SavedViewsBar savedViews={data.savedViews ?? []} recentFilters={data.recentFilters ?? []} onLoad={loadSavedView} onDelete={deleteSavedView} />}
        {view === 'dashboard' && <Dashboard data={data} tasks={filteredTasks} search={search} filterStatus={filterStatus} filterPriority={filterPriority} filterFeature={filterFeature} filterWaiting={filterWaiting} filterMap={filterMap} filterEffect={filterEffect} filterTag={filterTag} filterFeedback={filterFeedback} filterChangelist={filterChangelist} filterReflection={filterReflection} filterCompletion={filterCompletion} showAdvancedFilters={showAdvancedFilters} setShowAdvancedFilters={setShowAdvancedFilters} setFilterStatus={setFilterStatus} setFilterPriority={setFilterPriority} setFilterFeature={setFilterFeature} setFilterWaiting={setFilterWaiting} setFilterMap={setFilterMap} setFilterEffect={setFilterEffect} setFilterTag={setFilterTag} setFilterFeedback={setFilterFeedback} setFilterChangelist={setFilterChangelist} setFilterReflection={setFilterReflection} setFilterCompletion={setFilterCompletion} onOpenTask={openTask} onToggleFocus={toggleFocus} onQuickAction={(id, tab) => openTask(id, tab)} onSaveView={saveCurrentView} onLoadView={loadSavedView} onDeleteView={deleteSavedView} />}
        {view === 'all-tasks' && <AllTasks tasks={data.tasks} data={data} onOpenTask={openTask} onTogglePinned={togglePinned} onArchive={archiveTask} onRestore={restoreTask} onSaveView={(filters) => { const name = window.prompt('Name this All Tasks view'); if (!name?.trim()) return; setData((current) => ({ ...current, savedViews: [...(current.savedViews ?? []).filter((view) => view.name !== name.trim()), { id: makeId('view'), name: name.trim(), filters }] })); setToast(`Saved view: ${name.trim()}`) }} onLoadView={loadSavedView} />}
        {view === 'intake' && <LeanIntake draft={intake} setDraft={setIntake} onCreate={createTask} onCancel={() => setView('dashboard')} onCopy={() => copyText(buildClarificationMessage({ ...selectedTask, requirements: intake.requirements } as Task), 'Clarification note copied')} />}
        {view === 'templates' && <Templates templates={data.templates} setData={setData} onToast={setToast} onUse={useStartingPoint} />}
        {view === 'library' && <ReflectionLibrary tasks={data.tasks} onOpen={(id) => openTask(id, 'Reflection')} />}
        {view === 'families' && <FamiliesPage data={data} selectedFamilyId={selectedFamilyId} onSelectFamily={setSelectedFamilyId} onOpenTask={openTask} onOpenPipeline={openPipeline} />}
        {view === 'pipelines' && <PipelinesPage data={data} selectedPipelineId={selectedPipelineId} onSelectPipeline={setSelectedPipelineId} onOpenTask={openTask} onCreatePipeline={createPipeline} />}
        {view === 'workspace' && selectedTask && <>
          <TaskContextBar task={selectedTask} data={data} onOpenFamily={openFamily} onOpenPipeline={openPipeline} onOpenRelated={() => setRelatedPanelOpen(true)} onCreateRelated={() => setRelatedDialogOpen(true)} />
          {activeTab === 'Reflection' && <ReflectionPromotionBar task={selectedTask} onPromote={promoteLesson} onUseAsStartingPoint={useReflectionAsStartingPoint} />}
           <Workspace task={selectedTask} data={data} uiState={selectedTaskUIState} onUIStateChange={(patch) => updateTaskUIState(selectedTask.id, patch)} activeTab={activeTab} setActiveTab={setWorkspaceTab} setStage={setTaskStage} patchTask={patchTask} updateTask={updateTask} addHistory={addHistory} onBack={() => nav('dashboard')} onTogglePinned={() => togglePinned(selectedTask.id)} onArchive={() => archiveTask(selectedTask.id)} onRestore={() => restoreTask(selectedTask.id)} onCopy={copyText} newLogOpen={newLogOpen} setNewLogOpen={setNewLogOpen} logDraft={logDraft} setLogDraft={setLogDraft} addWorkLog={addWorkLog} promoteNote={promoteNote} newFeedbackOpen={newFeedbackOpen} setNewFeedbackOpen={setNewFeedbackOpen} feedbackDraft={feedbackDraft} setFeedbackDraft={setFeedbackDraft} addFeedback={addFeedback} addFollowUp={addFollowUp} onCreateRelated={() => setRelatedDialogOpen(true)} density={taskPageDensity} onDensityChange={setTaskPageDensity} messageType={messageType} setMessageType={setMessageType} messageTone={messageTone} setMessageTone={setMessageTone} messageFormat={messageFormat} setMessageFormat={setMessageFormat} messageOutput={messageOutput} setMessageOutput={setMessageOutput} />
        </>}
      </main>
      {view === 'workspace' && selectedTask && <RelatedWorkDrawer task={selectedTask} data={data} open={relatedPanelOpen} onClose={() => setRelatedPanelOpen(false)} onOpenTask={openTask} onOpenFamily={openFamily} onOpenPipeline={openPipeline} onCreateRelated={() => setRelatedDialogOpen(true)} onRemoveRelationship={removeRelationship} onLinkExisting={linkExistingTask} onMoveFamily={moveTaskToFamily} onFamilyContext={updateFamilyContext} onUpdateDecision={updateVariationDecision} />}
      {view === 'workspace' && selectedTask && <RelatedTaskDialog task={selectedTask} data={data} open={relatedDialogOpen} onClose={() => setRelatedDialogOpen(false)} onCreate={createRelatedTask} />}
      {toast && <div className="toast"><CheckCircle2 size={16} />{toast}</div>}
      <OfflineUpdatePrompt />
    </div>
  )
}

function ModeNotice({ online }: { online: boolean }) {
  return <div className={cn('mode-notice', APP_MODE.publicDemo ? 'public-demo' : 'local-mode')}><span className="mode-notice-dot" /><strong>{APP_MODE.publicDemo ? 'Public demo' : 'Local workspace'}</strong><span>{online ? 'Data stays in this browser.' : 'Offline — changes remain on this device.'}</span>{APP_MODE.publicDemo && <small>Do not upload sensitive company information to the public version.</small>}</div>
}

function Sidebar({ view, tasks, selectedTaskId, data, onNavigate, onOpenTask, onNewTask, onLibrary, onTogglePinned, online }: { view: View; tasks: Task[]; selectedTaskId?: string; data: AppData; onNavigate: (view: View) => void; onOpenTask: (id: string) => void; onNewTask: () => void; onLibrary: () => void; onTogglePinned: (id: string) => void; online: boolean }) {
  const pinnedIds = data.pinnedTaskIds ?? tasks.filter((task) => task.pinned).map((task) => task.id)
  const recentIds = data.recentTaskIds ?? []
  const pinned = pinnedIds.map((id) => tasks.find((task) => task.id === id)).filter(Boolean) as Task[]
  const recent = recentIds.map((id) => tasks.find((task) => task.id === id)).filter((task): task is Task => task !== undefined && !pinnedIds.includes(task.id)).slice(0, 5)
  const activeCount = tasks.filter((task) => task.lifecycle === 'Active').length
  const compactTask = (task: Task) => <div className="compact-task-row" key={task.id}><button className={cn('task-nav-item', selectedTaskId === task.id && 'active')} onClick={() => onOpenTask(task.id)}><span className={cn('task-dot', stageClass(task.stage))} /><span className="task-nav-copy"><strong>{task.name}</strong><small>{task.workType} · {task.effectType}</small></span></button><button className="sidebar-pin" title={pinnedIds.includes(task.id) ? 'Unpin task' : 'Pin task'} onClick={() => onTogglePinned(task.id)}>{pinnedIds.includes(task.id) ? '★' : '☆'}</button></div>
  return <aside className="sidebar">
    <div className="brand-lockup"><div className="brand-mark"><Zap size={17} /></div><div><strong>VFX / FLOW</strong><span>Personal assistant</span></div></div>
    <div className="side-rule" />
    <nav className="primary-nav" aria-label="Primary navigation">
      <button className={cn('nav-item', view === 'dashboard' && 'active')} onClick={() => onNavigate('dashboard')}><LayoutDashboard size={16} /><span>Dashboard</span><kbd>⌘1</kbd></button>
      <button className={cn('nav-item', view === 'intake' && 'active')} onClick={onNewTask}><Inbox size={16} /><span>Request intake</span><kbd>⌘N</kbd></button>
      <button className={cn('nav-item', view === 'templates' && 'active')} onClick={() => onNavigate('templates')}><BookOpen size={16} /><span>Starting points</span></button>
      <button className={cn('nav-item', view === 'library' && 'active')} onClick={onLibrary}><ClipboardCheck size={16} /><span>Reflection library</span></button>
      <button className={cn('nav-item', view === 'families' && 'active')} onClick={() => onNavigate('families')}><Layers3 size={16} /><span>Task families</span><b className="nav-count">{data.families?.length ?? 0}</b></button>
      <button className={cn('nav-item', view === 'pipelines' && 'active')} onClick={() => onNavigate('pipelines')}><GitBranch size={16} /><span>Pipeline cards</span><b className="nav-count">{data.pipelines?.length ?? 0}</b></button>
    </nav>
    <div className="nav-all-tasks-link"><button className="nav-item subtle" onClick={() => onNavigate('all-tasks')}><ListChecks size={15} /><span>All Tasks</span><b className="nav-count">{activeCount}</b></button></div>
    <div className="side-section-title"><span>PINNED</span><span>{pinned.length}/5</span></div>
    <div className="compact-task-list">{pinned.length ? pinned.map(compactTask) : <p className="sidebar-empty">Pin up to five tasks for quick access.</p>}</div>
    <div className="side-section-title"><span>RECENT</span><span>{recent.length}</span></div>
    <div className="compact-task-list">{recent.length ? recent.map(compactTask) : <p className="sidebar-empty">Opened tasks will appear here.</p>}</div>
    <div className="sidebar-bottom"><div className="local-state"><span className={cn('live-dot', !online && 'offline')} /> <span>{APP_MODE.publicDemo ? 'Public demo' : 'Local workspace'}</span><small>{online ? (APP_MODE.publicDemo ? 'Browser only' : 'Online') : 'Offline — changes remain on this device'}</small></div><button className="nav-item subtle"><Settings2 size={16} /><span>Preferences</span></button></div>
  </aside>
}

function Topbar({ search, setSearch, searchRef, onExport, onImport, onNewTask }: { search: string; setSearch: (value: string) => void; searchRef: React.RefObject<HTMLInputElement | null>; onExport: () => void; onImport: (event: React.ChangeEvent<HTMLInputElement>) => void; onNewTask: () => void }) {
  return <header className="topbar"><div className="search-box"><Search size={16} /><input ref={searchRef} value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search tasks, maps, effects, reflections…" aria-label="Global search" />{search && <button onClick={() => setSearch('')} aria-label="Clear search"><X size={14} /></button>}<kbd>⌘K</kbd></div><div className="top-actions"><label className="icon-button" title="Import JSON"><Upload size={16} /><input type="file" accept="application/json,.json" onChange={onImport} /></label><button className="icon-button" title="Export JSON" onClick={onExport}><Download size={16} /></button><div className="top-divider" /><span className="avatar">VF</span><button className="profile-button">VFX / FLOW <ChevronDown size={14} /></button><button className="new-task-button" onClick={onNewTask}><Plus size={16} />Quick capture</button></div></header>
}

function LegacyDashboard({ data, tasks, search, filterStatus, filterPriority, filterFeature, filterWaiting, setFilterStatus, setFilterPriority, setFilterFeature, setFilterWaiting, onOpenTask, onToggleFocus, onQuickAction }: { data: AppData; tasks: Task[]; search: string; filterStatus: string; filterPriority: string; filterFeature: string; filterWaiting: string; setFilterStatus: (value: string) => void; setFilterPriority: (value: string) => void; setFilterFeature: (value: string) => void; setFilterWaiting: (value: string) => void; onOpenTask: (id: string, tab?: WorkspaceTab) => void; onToggleFocus: (id: string) => void; onQuickAction: (id: string, tab: WorkspaceTab) => void }) {
  const inProgress = data.tasks.filter((task) => ['Blockout', 'Iterating', 'Ready to Start'].includes(task.stage)).length
  const waiting = data.tasks.filter((task) => task.stage === 'Waiting for Feedback').length + data.tasks.filter((task) => task.stage === 'Needs Clarification').length
  const ready = data.tasks.filter((task) => task.stage === 'Ready to Submit').length
  const verification = data.tasks.filter((task) => ['Submitted', 'Waiting for Verification'].includes(task.stage)).length
  const blocked = data.tasks.filter((task) => task.stage === 'Blocked').length
  const focusTasks = data.focusTaskIds.map((id) => data.tasks.find((task) => task.id === id)).filter(Boolean) as Task[]
  const followUps = data.tasks.flatMap((task) => task.followUps.filter((follow) => follow.status !== 'Done').map((follow) => ({ task, follow }))).sort((a, b) => (a.follow.reminderDate || '9999').localeCompare(b.follow.reminderDate || '9999'))
  const features = Array.from(new Set(data.tasks.map((task) => task.feature).filter(Boolean)))
  return <div className="page-content dashboard-page"><div className="page-heading"><div><p className="eyebrow"><span className="pulse" />TODAY / WORK QUEUE</p><h1>Your VFX queue</h1><p className="page-subtitle">A clean handoff between request, iteration, and submit.</p></div><div className="heading-actions"><button className="secondary-button"><Bell size={15} />{followUps.length} follow-ups</button><button className="secondary-button"><Archive size={15} />Local backup</button></div></div>
    <section className="metric-grid"><Metric label="In progress" value={inProgress} detail="active passes" icon={<Zap size={16} />} accent="cyan" /><Metric label="Needs a response" value={waiting} detail="clarification or feedback" icon={<MessageSquare size={16} />} accent="amber" /><Metric label="Ready to submit" value={ready} detail="presubmit next" icon={<Send size={16} />} accent="violet" /><Metric label="Awaiting verification" value={verification} detail="submitted / unverified" icon={<CheckCircle2 size={16} />} accent="green" /><Metric label="Blocked" value={blocked} detail="needs a dependency" icon={<ShieldAlert size={16} />} accent="red" /></section>
    <div className="dashboard-grid"><section className="panel focus-panel"><div className="panel-header"><div><p className="panel-kicker">TODAY FOCUS <span className="count-pill">{focusTasks.length}/3</span></p><h2>Keep the handoff moving</h2></div><button className="ghost-button">Edit focus</button></div><div className="focus-list">{focusTasks.length ? focusTasks.map((task) => <TaskRow key={task.id} task={task} onOpen={onOpenTask} onFocus={onToggleFocus} compact />) : <EmptyState icon={<Target size={20} />} title="Choose up to three focus tasks" detail="Use the star on any task below to pull it into today’s working set." />}</div></section><section className="panel follow-panel"><div className="panel-header"><div><p className="panel-kicker">FOLLOW-UP QUEUE</p><h2>Don’t lose the thread</h2></div><button className="ghost-button">View all</button></div><div className="follow-list">{followUps.length ? followUps.slice(0, 4).map(({ task, follow }) => <button key={follow.id} className="follow-row" onClick={() => onOpenTask(task.id, 'Overview')}><span className="follow-icon"><Clock3 size={15} /></span><span><strong>{follow.kind}</strong><small>{task.name} · {follow.nextAction}</small></span><em className={follow.reminderDate && new Date(`${follow.reminderDate}T12:00:00`) < new Date() ? 'overdue' : ''}>{follow.reminderDate ? dueLabel(follow.reminderDate) : 'No date'}</em></button>) : <EmptyState icon={<Check size={20} />} title="No open follow-ups" detail="Submitted tasks will show downstream reminders here." />}</div></section></div>
    <section className="panel task-board"><div className="panel-header board-header"><div><p className="panel-kicker">WORK QUEUE <span className="count-pill">{tasks.length} visible</span></p><h2>All VFX tasks</h2></div><div className="view-switcher"><button className="active"><ListChecks size={15} />List</button><button><FolderKanban size={15} />Stage</button></div></div><div className="filter-bar"><div className="filter-label"><Filter size={14} />Filter</div><Select value={filterStatus} onChange={setFilterStatus} options={['All status', ...STAGES]} /><Select value={filterPriority} onChange={setFilterPriority} options={['All priorities', ...PRIORITIES]} /><Select value={filterFeature} onChange={setFilterFeature} options={['All features', ...features]} /><Select value={filterWaiting} onChange={setFilterWaiting} options={['All blockers', ...DISCIPLINES.filter((item) => item !== 'Nobody'), 'Nobody']} />{search && <span className="search-result">Searching “{search}”</span>}</div><div className="task-list">{tasks.length ? tasks.map((task) => <TaskRow key={task.id} task={task} onOpen={onOpenTask} onFocus={onToggleFocus} onQuickAction={onQuickAction} />) : <EmptyState icon={<Search size={20} />} title="No matching tasks" detail="Try clearing a filter or searching a different term." />}</div></section>
  </div>
}

function Dashboard({ data, tasks, filterStatus, filterPriority, filterFeature, filterWaiting, filterMap, filterEffect, filterTag, filterFeedback, filterChangelist, filterReflection, filterCompletion, showAdvancedFilters, setShowAdvancedFilters, setFilterStatus, setFilterPriority, setFilterFeature, setFilterWaiting, setFilterMap, setFilterEffect, setFilterTag, setFilterFeedback, setFilterChangelist, setFilterReflection, setFilterCompletion, onOpenTask, onToggleFocus, onQuickAction, onSaveView, onLoadView, onDeleteView }: { data: AppData; tasks: Task[]; search: string; filterStatus: string; filterPriority: string; filterFeature: string; filterWaiting: string; filterMap: string; filterEffect: string; filterTag: string; filterFeedback: string; filterChangelist: string; filterReflection: string; filterCompletion: string; showAdvancedFilters: boolean; setShowAdvancedFilters: (value: boolean) => void; setFilterStatus: (value: string) => void; setFilterPriority: (value: string) => void; setFilterFeature: (value: string) => void; setFilterWaiting: (value: string) => void; setFilterMap: (value: string) => void; setFilterEffect: (value: string) => void; setFilterTag: (value: string) => void; setFilterFeedback: (value: string) => void; setFilterChangelist: (value: string) => void; setFilterReflection: (value: string) => void; setFilterCompletion: (value: string) => void; onOpenTask: (id: string, tab?: WorkspaceTab) => void; onToggleFocus: (id: string) => void; onQuickAction: (id: string, tab: WorkspaceTab) => void; onSaveView?: () => void; onLoadView: (view: SavedView) => void; onDeleteView: (id: string) => void }) {
  const activeNow = tasks.filter((task) => !['Needs Clarification', 'Waiting for Feedback', 'Blocked', 'Waiting for Verification', 'Complete'].includes(task.stage)).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))
  const waiting = tasks.filter((task) => ['Needs Clarification', 'Waiting for Feedback', 'Blocked', 'Waiting for Verification'].includes(task.stage))
  const recent = tasks.filter((task) => ['Submitted', 'Complete', 'Waiting for Verification'].includes(task.stage)).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)).slice(0, 5)
  const mapOptions = Array.from(new Set(data.tasks.map((task) => task.mapMode).filter(Boolean)))
  const featureOptions = Array.from(new Set(data.tasks.map((task) => task.feature).filter(Boolean)))
  const tagOptions = Array.from(new Set(data.tasks.flatMap((task) => task.tags))).sort()
  const activeChips: Array<{ label: string; clear: () => void }> = []
  if (filterMap !== 'All maps') activeChips.push({ label: filterMap, clear: () => setFilterMap('All maps') })
  if (filterEffect !== 'All effect types') activeChips.push({ label: filterEffect, clear: () => setFilterEffect('All effect types') })
  if (filterTag !== 'All tags') activeChips.push({ label: filterTag, clear: () => setFilterTag('All tags') })
  if (filterStatus !== 'All status') activeChips.push({ label: filterStatus, clear: () => setFilterStatus('All status') })
  if (filterPriority !== 'All priorities') activeChips.push({ label: filterPriority, clear: () => setFilterPriority('All priorities') })
  if (filterWaiting !== 'All blockers') activeChips.push({ label: `Waiting · ${filterWaiting}`, clear: () => setFilterWaiting('All blockers') })
  if (filterFeedback !== 'All feedback') activeChips.push({ label: filterFeedback, clear: () => setFilterFeedback('All feedback') })
  if (filterChangelist !== 'All changelists') activeChips.push({ label: filterChangelist, clear: () => setFilterChangelist('All changelists') })
  if (filterReflection !== 'All reflections') activeChips.push({ label: filterReflection, clear: () => setFilterReflection('All reflections') })
  if (filterCompletion !== 'Active and completed') activeChips.push({ label: filterCompletion, clear: () => setFilterCompletion('Active and completed') })
  const clearFilters = () => { setFilterMap('All maps'); setFilterEffect('All effect types'); setFilterTag('All tags'); setFilterStatus('All status'); setFilterPriority('All priorities'); setFilterWaiting('All blockers'); setFilterFeedback('All feedback'); setFilterChangelist('All changelists'); setFilterReflection('All reflections'); setFilterCompletion('Active and completed') }
  const waitingGroups = [
    { label: 'Design', tasks: waiting.filter((task) => task.stage === 'Needs Clarification' || task.requestingDiscipline === 'Design') },
    { label: 'Tech Design', tasks: waiting.filter((task) => task.requestingDiscipline === 'Tech Design') },
    { label: 'Art or Animation', tasks: waiting.filter((task) => ['Art', 'Animation'].includes(task.requestingDiscipline)) },
    { label: 'SFX', tasks: waiting.filter((task) => task.requestingDiscipline === 'Audio' || task.tags.includes('SFX')) },
    { label: 'Build or verification', tasks: waiting.filter((task) => ['Waiting for Verification', 'Production'].includes(task.stage === 'Waiting for Verification' ? 'Production' : task.requestingDiscipline)) },
  ].filter((group) => group.tasks.length)
  return <div className="page-content dashboard-page personal-dashboard"><div className="page-heading"><div><p className="eyebrow"><span className="pulse" />PERSONAL WORKSPACE / JUL 28 2026</p><h1>What needs your attention?</h1><p className="page-subtitle">Capture quickly, keep the next action clear, and make past VFX work reusable.</p></div><div className="heading-actions"><button className="secondary-button" onClick={() => onOpenTask(data.tasks.find((task) => task.stage === 'Ready to Submit')?.id || data.tasks[0].id, 'Submission')}><Send size={14} />Prepare next submit</button></div></div><div className="compact-status-strip"><span><i className="strip-dot cyan" />{activeNow.length} active</span><span><i className="strip-dot amber" />{waiting.length} waiting</span><span><i className="strip-dot violet" />{recent.length} recent</span><span className="strip-note">Local-only · autosaved</span></div><section className="now-section"><div className="section-intro"><div><p className="panel-kicker">NOW</p><h2>Direct action</h2><p>Work that can move with your next small decision.</p></div><span className="section-count">{activeNow.length} tasks</span></div><div className="action-task-list">{activeNow.length ? activeNow.map((task) => <ActionTaskRow key={task.id} task={task} onOpen={onOpenTask} onFocus={onToggleFocus} onQuickAction={onQuickAction} />) : <EmptyState icon={<Check size={20} />} title="Nothing asking for your hands" detail="Capture a new request or open the waiting list to review dependencies." />}</div></section><div className="dashboard-columns"><section className="light-section waiting-section"><div className="section-intro"><div><p className="panel-kicker">WAITING</p><h2>Blocked by someone or something</h2></div><span className="section-count">{waiting.length}</span></div>{waitingGroups.length ? <div className="waiting-groups">{waitingGroups.map((group) => <div className="waiting-group" key={group.label}><div className="waiting-group-head"><span className="waiting-group-dot" />{group.label}<span>{group.tasks.length}</span></div>{group.tasks.slice(0, 4).map((task) => <button className="waiting-task" key={task.id} onClick={() => onOpenTask(task.id)}><span><strong>{task.name}</strong><small>{task.mapMode || task.feature} · {task.nextAction}</small></span><ArrowRight size={13} /></button>)}</div>)}</div> : <EmptyState icon={<Check size={20} />} title="No waiting tasks" detail="The queue is clear." />}</section><section className="light-section recent-section"><div className="section-intro"><div><p className="panel-kicker">RECENT</p><h2>Submitted and complete</h2></div><span className="section-count">{recent.length}</span></div>{recent.length ? <div className="recent-list">{recent.map((task) => <button className="recent-task" key={task.id} onClick={() => onOpenTask(task.id, task.stage === 'Complete' ? 'Reflection' : 'Submission')}><div className="recent-task-top"><strong>{task.name}</strong><span className={cn('status-badge', stageClass(task.stage))}>{task.stage}</span></div><small>{task.mapMode || task.feature} · {task.submission.changelist ? `CL ${task.submission.changelist}` : 'No CL recorded'}</small><div className="recent-meta"><span>{formatDate(task.updatedAt)}</span><span className={task.reflection.completed ? 'reflection-done' : 'reflection-open'}>{task.reflection.completed ? 'Reflection complete' : 'Reflection not started'}</span></div></button>)}</div> : <EmptyState icon={<Archive size={20} />} title="No recent handoffs" detail="Submitted and completed work will stay easy to revisit here." />}</section></div><section className="workspace-filter-section"><div className="section-intro"><div><p className="panel-kicker">ALL TASKS</p><h2>Find previous work</h2><p>Filter by context, effect type, or what still needs closure.</p></div><div className="filter-actions"><button className="ghost-button" onClick={() => setShowAdvancedFilters(!showAdvancedFilters)}><Filter size={14} />{showAdvancedFilters ? 'Hide filters' : 'Show filters'}</button><button className="ghost-button" onClick={clearFilters} disabled={!activeChips.length}>Clear all</button><button className="secondary-button" onClick={onSaveView}><BookOpen size={14} />Save view</button></div></div><div className="filter-chip-row">{activeChips.length ? activeChips.map((chip) => <button className="active-filter-chip" key={chip.label} onClick={chip.clear}>{chip.label}<X size={12} /></button>) : <span className="muted">No filters applied</span>}</div>{showAdvancedFilters && <div className="filter-panel"><Select value={filterMap} onChange={setFilterMap} options={['All maps', ...mapOptions]} /><Select value={filterFeature} onChange={setFilterFeature} options={['All features', ...featureOptions]} /><Select value={filterEffect} onChange={setFilterEffect} options={['All effect types', ...EFFECT_TYPES]} /><Select value={filterTag} onChange={setFilterTag} options={['All tags', ...tagOptions]} /><Select value={filterStatus} onChange={setFilterStatus} options={['All status', ...STAGES]} /><Select value={filterPriority} onChange={setFilterPriority} options={['All priorities', ...PRIORITIES]} /><Select value={filterWaiting} onChange={setFilterWaiting} options={['All blockers', ...DISCIPLINES]} /><Select value={filterFeedback} onChange={setFilterFeedback} options={['All feedback', 'Unresolved feedback', 'No unresolved feedback']} /><Select value={filterChangelist} onChange={setFilterChangelist} options={['All changelists', 'Has changelist', 'No changelist']} /><Select value={filterReflection} onChange={setFilterReflection} options={['All reflections', 'Has reflection', 'No reflection']} /><Select value={filterCompletion} onChange={setFilterCompletion} options={['Active and completed', 'Active only', 'Completed only']} /></div>}<div className="task-list personal-task-list">{tasks.length ? tasks.map((task) => <ActionTaskRow key={task.id} task={task} onOpen={onOpenTask} onFocus={onToggleFocus} onQuickAction={onQuickAction} />) : <EmptyState icon={<Search size={20} />} title="No matching work" detail="Clear a filter or try searching for a map, effect type, tag, or lesson." />}</div></section></div>
}

function ActionTaskRow({ task, onOpen, onFocus, onQuickAction }: { task: Task; onOpen: (id: string, tab?: WorkspaceTab) => void; onFocus: (id: string) => void; onQuickAction: (id: string, tab: WorkspaceTab) => void }) { return <div className="action-task-row"><button className="task-star" title="Toggle focus" onClick={() => onFocus(task.id)}><Target size={15} /></button><button className="action-task-main" onClick={() => onOpen(task.id)}><div className="action-task-primary"><strong>{task.name}</strong><small>{task.mapMode || 'Map not set'} · {task.effectType} · {task.tags.slice(0, 2).join(', ') || 'No tags'}</small></div><div className="next-action-emphasis"><span>NEXT ACTION</span><strong>{task.nextAction || 'Define the next action'}</strong></div><span className={cn('status-badge', stageClass(task.stage))}>{task.stage}</span><span className="updated-cell">{formatRelative(task.updatedAt)}</span></button><div className="row-actions"><button title="Add note" onClick={() => onQuickAction(task.id, 'Work Log')}><Plus size={14} /></button><button title="Ask for feedback" onClick={() => onQuickAction(task.id, 'Feedback')}><MessageSquare size={14} /></button></div></div> }

function LegacySearchResults({ tasks, query, onOpen }: { tasks: Task[]; query: string; onOpen: (id: string, tab?: WorkspaceTab) => void }) { const matches = tasks.map((task) => { const q = query.toLowerCase(); const reasons: Array<{ label: string; tab?: WorkspaceTab }> = []; if (task.name.toLowerCase().includes(q)) reasons.push({ label: `Matched task: ${task.name}` }); if (task.mapMode.toLowerCase().includes(q)) reasons.push({ label: `Matched map: ${task.mapMode}` }); if (task.effectType.toLowerCase().includes(q)) reasons.push({ label: `Matched effect: ${task.effectType}` }); const tag = task.tags.find((item) => item.toLowerCase().includes(q)); if (tag) reasons.push({ label: `Matched tag: ${tag}` }); if (task.jira.toLowerCase().includes(q) || task.submission.changelist.toLowerCase().includes(q)) reasons.push({ label: `Matched CL or Jira: ${task.submission.changelist || task.jira}`, tab: 'Submission' }); const reflectionText = JSON.stringify(task.reflection).toLowerCase(); if (reflectionText.includes(q)) reasons.push({ label: 'Matched reflection or lesson', tab: 'Reflection' }); const feedbackText = JSON.stringify([...task.feedback, ...task.workLogs]).toLowerCase(); if (feedbackText.includes(q)) reasons.push({ label: 'Matched feedback or work note', tab: 'Work Log' }); return { task, reasons }; }).filter((item) => item.reasons.length); const active = matches.filter(({ task }) => !['Complete', 'Submitted', 'Waiting for Verification'].includes(task.stage)); const completed = matches.filter(({ task }) => ['Complete', 'Submitted', 'Waiting for Verification'].includes(task.stage)); return <div className="search-results"><div className="search-results-head"><span>SEARCH RESULTS</span><strong>{matches.length} matches for “{query}”</strong></div>{active.length > 0 && <SearchResultGroup label="Active tasks" items={active} onOpen={onOpen} />}{completed.length > 0 && <SearchResultGroup label="Completed tasks" items={completed} onOpen={onOpen} />}{!matches.length && <div className="search-empty">No tasks, notes, feedback, changelists, or reflections match that search.</div>}</div> }

function SearchResults({ tasks, data, query, onOpen }: { tasks: Task[]; data: AppData; query: string; onOpen: (id: string, tab?: WorkspaceTab) => void }) {
  const q = query.trim().toLowerCase()
  const matches = tasks.map((task) => {
    const reasons: Array<{ label: string; tab?: WorkspaceTab }> = []
    const text = JSON.stringify(task).toLowerCase()
    if (task.name.toLowerCase().includes(q)) reasons.push({ label: `Matched task: ${task.name}` })
    if (task.workType.toLowerCase().includes(q)) reasons.push({ label: `Matched work type: ${task.workType}` })
    if (task.effectType.toLowerCase().includes(q)) reasons.push({ label: `Matched effect type: ${task.effectType}` })
    if (task.mapMode.toLowerCase().includes(q)) reasons.push({ label: `Matched map: ${task.mapMode}` })
    const family = (data.families ?? []).find((item) => item.id === task.familyId)
    if (family && JSON.stringify(family).toLowerCase().includes(q)) reasons.push({ label: `Matched family: ${family.name}` })
    const pipelines = (data.pipelines ?? []).filter((pipeline) => task.pipelineIds?.includes(pipeline.id))
    if (pipelines.some((pipeline) => JSON.stringify(pipeline).toLowerCase().includes(q))) reasons.push({ label: `Matched pipeline: ${pipelines.find((pipeline) => JSON.stringify(pipeline).toLowerCase().includes(q))?.name}` })
    if ((task.relationships ?? []).some((relation) => JSON.stringify(relation).toLowerCase().includes(q))) reasons.push({ label: 'Matched task relationship' })
    const tag = task.tags.find((item) => item.toLowerCase().includes(q)); if (tag) reasons.push({ label: `Matched tag: ${tag}` })
    if (task.bugFix?.observedBehavior.toLowerCase().includes(q)) reasons.push({ label: `Matched bug symptom: ${task.bugFix.observedBehavior}`, tab: 'Overview' })
    if (task.bugFix?.reproductionSteps.some((item) => item.label.toLowerCase().includes(q))) reasons.push({ label: 'Matched reproduction step', tab: 'Overview' })
    if (task.bugFix?.rootCause.toLowerCase().includes(q)) reasons.push({ label: `Matched root cause: ${task.bugFix.rootCause}`, tab: 'Overview' })
    if (task.optimization?.changes.toLowerCase().includes(q) || task.optimization?.currentIssue.toLowerCase().includes(q)) reasons.push({ label: 'Matched optimization note', tab: 'Overview' })
    if (task.hookup?.gameplayEventName.toLowerCase().includes(q) || task.hookup?.scriptableName.toLowerCase().includes(q)) reasons.push({ label: 'Matched hookup event name', tab: 'Overview' })
    if (task.jira.toLowerCase().includes(q) || task.submission.changelist.toLowerCase().includes(q)) reasons.push({ label: `Matched CL or Jira: ${task.submission.changelist || task.jira}`, tab: 'Submission' })
    if (JSON.stringify(task.reflection).toLowerCase().includes(q)) reasons.push({ label: 'Matched reflection or lesson', tab: 'Reflection' })
    if ((data.promotedLessons ?? []).some((lesson) => lesson.sourceTaskId === task.id && JSON.stringify(lesson).toLowerCase().includes(q))) reasons.push({ label: 'Matched promoted lesson', tab: 'Reflection' })
    if (text.includes(q) && !reasons.length) reasons.push({ label: 'Matched task workspace notes' })
    return { task, reasons }
  }).filter((item) => item.reasons.length)
  const active = matches.filter(({ task }) => task.lifecycle === 'Active')
  const completed = matches.filter(({ task }) => task.lifecycle === 'Completed')
  const archived = matches.filter(({ task }) => task.lifecycle === 'Archived')
  return <div className="search-results"><div className="search-results-head"><span>SEARCH RESULTS</span><strong>{matches.length} matches for “{query}”</strong></div>{active.length > 0 && <SearchResultGroup label="Active tasks" items={active} onOpen={onOpen} />}{completed.length > 0 && <SearchResultGroup label="Completed tasks" items={completed} onOpen={onOpen} />}{archived.length > 0 && <SearchResultGroup label="Archived tasks" items={archived} onOpen={onOpen} />}{!matches.length && <div className="search-empty">No tasks, symptoms, notes, changelists, reflections, or work-type details match that search.</div>}</div>
}

function SearchResultGroup({ label, items, onOpen }: { label: string; items: Array<{ task: Task; reasons: Array<{ label: string; tab?: WorkspaceTab }> }>; onOpen: (id: string, tab?: WorkspaceTab) => void }) { return <div className="search-result-group"><p>{label}</p>{items.slice(0, 5).map(({ task, reasons }) => <button key={task.id} onClick={() => onOpen(task.id, reasons[0].tab)}><span><strong>{task.name}</strong><small>{reasons[0].label}</small></span><ArrowRight size={14} /></button>)}</div> }

function Metric({ label, value, detail, icon, accent }: { label: string; value: number; detail: string; icon: React.ReactNode; accent: string }) { return <div className="metric-card"><div className={cn('metric-icon', accent)}>{icon}</div><div><span>{label}</span><strong>{value}</strong><small>{detail}</small></div></div> }

function TaskRow({ task, onOpen, onFocus, onQuickAction, compact }: { task: Task; onOpen: (id: string) => void; onFocus: (id: string) => void; onQuickAction?: (id: string, tab: WorkspaceTab) => void; compact?: boolean }) {
  const isFocus = task.id && false
  return <div className={cn('task-row', compact && 'compact')}><button className="task-star" title="Toggle Today Focus" onClick={() => onFocus(task.id)}><Target size={15} /></button><button className="task-row-main" onClick={() => onOpen(task.id)}><span className="task-row-title"><strong>{task.name}</strong><small>{task.feature} <span>•</span> {task.jira || 'No Jira ID'}</small></span><span className={cn('status-badge', stageClass(task.stage))}>{task.stage}</span><span className={cn('priority-chip', task.priority.toLowerCase())}>{task.priority}</span><span className="waiting-cell">{task.blocker ? <><span className="discipline-dot" />{task.blocker.replace('Waiting on ', '').slice(0, 28)}{task.blocker.length > 28 ? '…' : ''}</> : <span className="muted">—</span>}</span><span className="updated-cell">{formatRelative(task.updatedAt)}</span><span className="next-cell">{task.nextAction || 'No next action'}</span></button><div className="row-actions"><button title="Add work log" onClick={() => onQuickAction?.(task.id, 'Work Log')}><Plus size={14} /></button><button title="Request feedback" onClick={() => onQuickAction?.(task.id, 'Feedback')}><MessageSquare size={14} /></button><button title="More"><MoreHorizontal size={14} /></button></div></div>
}

function LegacyIntake({ draft, setDraft, onCreate, onCancel, onCopy }: { draft: IntakeDraft; setDraft: React.Dispatch<React.SetStateAction<IntakeDraft>>; onCreate: () => void; onCancel: () => void; onCopy: () => void }) {
  const patch = (key: keyof IntakeDraft, value: string | Priority) => setDraft((current) => ({ ...current, [key]: value }))
  const patchReq = (key: keyof RequirementBreakdown, value: string | string[]) => setDraft((current) => ({ ...current, requirements: { ...current.requirements, [key]: value } }))
  const toggleArray = (key: 'requiredStates' | 'missingInfo', value: string) => setDraft((current) => { const currentValues = current.requirements[key]; return { ...current, requirements: { ...current.requirements, [key]: currentValues.includes(value) ? currentValues.filter((item) => item !== value) : [...currentValues, value] } } })
  const missingCount = draft.requirements.missingInfo.length
}

function LegacyQuickCapture({ draft, setDraft, onCreate, onCancel, onCopy }: { draft: IntakeDraft; setDraft: React.Dispatch<React.SetStateAction<IntakeDraft>>; onCreate: () => void; onCancel: () => void; onCopy: () => void }) {
  const [showDetails, setShowDetails] = useState(false)
  const [suggestions, setSuggestions] = useState<{ effectType?: EffectType; mapMode?: string; discipline?: string; missing: string[] }>({ missing: [] })
  const patch = (key: keyof IntakeDraft, value: string | Priority | EffectType | string[] | Stage) => setDraft((current) => ({ ...current, [key]: value }))
  const patchReq = (key: keyof RequirementBreakdown, value: string | string[]) => setDraft((current) => ({ ...current, requirements: { ...current.requirements, [key]: value } }))
  const toggleTag = (tag: string) => setDraft((current) => ({ ...current, tags: current.tags.includes(tag) ? current.tags.filter((item) => item !== tag) : [...current.tags, tag] }))
  const extract = () => {
    const text = draft.rawRequest.toLowerCase()
    const effectType = /portal|teleport|rift/.test(text) ? 'Portal' : /charge|buildup|energy ball/.test(text) ? 'Charge-up' : /dust|debris|destruction/.test(text) ? 'Destruction' : /transform|model swap|ghost/.test(text) ? 'Material transition' : undefined
    const mapMode = /warzone|foundry|temple|manor|terminal/.exec(text)?.[0]
    const discipline = /design asked|design wants|design/.test(text) ? 'Design' : /tech design|scriptable/.test(text) ? 'Tech Design' : undefined
    const missing = [!/(trigger|when|on )/.test(text) ? 'Trigger is unclear' : '', !/(second|duration|timing|early|late)/.test(text) ? 'Timing is unclear' : '', !/(map|room|platform|location|distance)/.test(text) ? 'Location is unclear' : ''].filter(Boolean)
    setSuggestions({ effectType: effectType as EffectType | undefined, mapMode, discipline, missing })
  }
  const applySuggestion = (key: 'effectType' | 'mapMode' | 'requestingDiscipline', value: string) => patch(key, value as EffectType)
  const selectedMissing = suggestions.missing.length ? suggestions.missing : draft.requirements.missingInfo
  return <div className="page-content intake-page quick-capture-page"><div className="page-heading"><div><button className="back-link" onClick={onCancel}><ArrowLeft size={15} />Back to workspace</button><p className="eyebrow">QUICK CAPTURE / NEW TASK</p><h1>Get the ask out of your head</h1><p className="page-subtitle">Paste the note, give it a name, and organize it when you’re ready.</p></div><span className="local-badge"><span className="live-dot" />Saved locally</span></div><div className="quick-capture-layout"><section className="panel capture-panel"><SectionHeader kicker="CAPTURE" title="Start with the smallest useful brief" detail="Only the task name is needed to save. Everything else can wait." /><div className="form-grid two"><Field label="Task name" required value={draft.name} onChange={(value) => patch('name', value)} placeholder="e.g. Portal activation pass" /><Field label="Map or mode" value={draft.mapMode} onChange={(value) => patch('mapMode', value)} placeholder="e.g. Warzone / Foundry" /><Field label="Effect type" value={draft.effectType} onChange={(value) => patch('effectType', value)} options={EFFECT_TYPES} /><Field label="Jira ID or link" value={draft.jira} onChange={(value) => patch('jira', value)} placeholder="Optional" /><Field label="Current status" value={draft.stage} onChange={(value) => patch('stage', value)} options={STAGES} /><Field label="Next action" value={draft.nextAction} onChange={(value) => patch('nextAction', value)} placeholder="Optional: what should happen next?" /><Field label="Priority" value={draft.priority} onChange={(value) => patch('priority', value as Priority)} options={PRIORITIES} /></div><div className="field-block"><div className="field-label">Tags <span className="muted">optional</span></div><div className="chip-grid">{EFFECT_TAGS.map((tag) => <button type="button" key={tag} className={cn('select-chip', draft.tags.includes(tag) && 'selected')} onClick={() => toggleTag(tag)}>{draft.tags.includes(tag) && <Check size={12} />}{tag}</button>)}</div></div><Field label="Raw request or note" required type="textarea" value={draft.rawRequest} onChange={(value) => patch('rawRequest', value)} placeholder="Paste the Slack message, Jira description, or rough note here…" /><div className="capture-actions"><button className="secondary-button" onClick={extract}><Sparkles size={14} />Extract suggestions</button><button className="primary-button" onClick={onCreate}><Plus size={15} />Save task</button></div>{suggestions.effectType || suggestions.mapMode || suggestions.discipline || suggestions.missing.length ? <div className="suggestion-box"><div className="suggestion-head"><div><span className="panel-kicker">LOCAL SUGGESTIONS</span><h3>Review before applying</h3></div><span className="soft-chip">No external AI</span></div><p className="muted-copy">These guesses use simple keyword matching in this note. Nothing changes until you confirm it.</p><div className="suggestion-list">{suggestions.effectType && <Suggestion label="Effect type" value={suggestions.effectType} onApply={() => applySuggestion('effectType', suggestions.effectType!)} />}{suggestions.mapMode && <Suggestion label="Map or mode" value={suggestions.mapMode} onApply={() => applySuggestion('mapMode', suggestions.mapMode!)} />}{suggestions.discipline && <Suggestion label="Requesting discipline" value={suggestions.discipline} onApply={() => applySuggestion('requestingDiscipline', suggestions.discipline!)} />}{suggestions.missing.map((item) => <div className="suggestion-missing" key={item}><ShieldAlert size={13} />Possible missing info: {item}</div>)}</div></div> : null}</section><aside className="capture-side"><section className="panel capture-side-card"><div className="panel-kicker">ADVANCED DETAILS</div><button className="details-toggle" onClick={() => setShowDetails(!showDetails)}><span>Add production details</span>{showDetails ? <ChevronDown size={15} /> : <ArrowRight size={15} />}</button>{showDetails && <div className="advanced-details"><Field label="Feature name" value={draft.feature} onChange={(value) => patch('feature', value)} /><Field label="Request source" value={draft.source} onChange={(value) => patch('source', value)} /><Field label="Requesting discipline" value={draft.requestingDiscipline} onChange={(value) => patch('requestingDiscipline', value)} options={DISCIPLINES.filter((item) => item !== 'Nobody')} /><Field label="Requesting person" value={draft.requester} onChange={(value) => patch('requester', value)} /><Field label="Target date" type="date" value={draft.targetDate} onChange={(value) => patch('targetDate', value)} /><Field label="Gameplay purpose" value={draft.requirements.gameplayPurpose} onChange={(value) => patchReq('gameplayPurpose', value)} /><Field label="What the player should understand" value={draft.requirements.playerUnderstanding} onChange={(value) => patchReq('playerUnderstanding', value)} /><Field label="Trigger condition" value={draft.requirements.triggerCondition} onChange={(value) => patchReq('triggerCondition', value)} /><Field label="Start event" value={draft.requirements.startEvent} onChange={(value) => patchReq('startEvent', value)} /><Field label="End event" value={draft.requirements.endEvent} onChange={(value) => patchReq('endEvent', value)} /><Field label="Duration" value={draft.requirements.duration} onChange={(value) => patchReq('duration', value)} /><Field label="Viewing distance" value={draft.requirements.viewingDistance} onChange={(value) => patchReq('viewingDistance', value)} /><Field label="Technical constraints" type="textarea" value={draft.requirements.technicalConstraints} onChange={(value) => patchReq('technicalConstraints', value)} /><Field label="Performance concerns" type="textarea" value={draft.requirements.performanceConcerns} onChange={(value) => patchReq('performanceConcerns', value)} /><Field label="Dependencies" type="textarea" value={draft.requirements.dependencies} onChange={(value) => patchReq('dependencies', value)} /></div>}</section><section className="panel capture-side-card clarification-card"><div className="panel-kicker">OPTIONAL CLARIFICATION</div><p className="muted-copy">Keep unanswered questions visible without blocking capture.</p><div className="message-preview">“{buildClarificationMessage({ ...({} as Task), requirements: { ...draft.requirements, missingInfo: selectedMissing } })}”</div><button className="secondary-button full-width" onClick={onCopy}><Copy size={14} />Copy note</button></section></aside></div></div>
}

function Intake({ draft, setDraft, onCreate, onCancel, onCopy }: { draft: IntakeDraft; setDraft: React.Dispatch<React.SetStateAction<IntakeDraft>>; onCreate: () => void; onCancel: () => void; onCopy: () => void }) {
  const [showDetails, setShowDetails] = useState(false)
  const [suggestions, setSuggestions] = useState<{ effectType?: EffectType; mapMode?: string; workType?: WorkType; discipline?: string; missing: string[] }>({ missing: [] })
  const patch = (key: keyof IntakeDraft, value: string | Priority | EffectType | WorkType | string[] | Stage) => setDraft((current) => ({ ...current, [key]: value }))
  const toggleTag = (tag: string) => setDraft((current) => ({ ...current, tags: current.tags.includes(tag) ? current.tags.filter((item) => item !== tag) : [...current.tags, tag] }))
  const extract = () => {
    const text = draft.rawRequest.toLowerCase()
    const effectType = /portal|teleport|rift/.test(text) ? 'Portal' : /charge|buildup|energy/.test(text) ? 'Charge-up' : /dust|debris|destruction|break/.test(text) ? 'Destruction' : /transform|model swap|ghost/.test(text) ? 'Material Transition' : undefined
    const workType = /bug|does not trigger|broken|repro/.test(text) ? 'Bug Fix' : /optimization|performance|particle count|frame rate/.test(text) ? 'Optimization' : /event name|hookup|integration|scriptable/.test(text) ? 'Hookup / Integration' : undefined
    const mapMode = /warzone|foundry|temple|manor|terminal/.exec(text)?.[0]
    const discipline = /tech design|scriptable/.test(text) ? 'Tech Design' : /design asked|design wants|design/.test(text) ? 'Design' : undefined
    const missing = [!/(trigger|when|on )/.test(text) ? 'Trigger is unclear' : '', !/(second|duration|timing|early|late)/.test(text) ? 'Timing is unclear' : '', !/(map|room|platform|location|distance)/.test(text) ? 'Location is unclear' : ''].filter(Boolean)
    setSuggestions({ effectType: effectType as EffectType | undefined, workType, mapMode, discipline, missing })
  }
  const rawPlaceholder = draft.workType === 'Bug Fix' ? 'Paste the bug report, reproduction note, Slack message, or Jira description.' : draft.workType === 'Optimization' ? 'Describe the performance concern and the desired visual result.' : 'Paste the VFX request, Design note, or Jira description.'
  const selectedMissing = suggestions.missing.length ? suggestions.missing : draft.requirements.missingInfo
  return <div className="page-content intake-page quick-capture-page"><div className="page-heading"><div><button className="back-link" onClick={onCancel}><ArrowLeft size={15} />Back to workspace</button><p className="eyebrow">QUICK CAPTURE / NEW TASK</p><h1>Capture the useful minimum</h1><p className="page-subtitle">Task name is enough to start. Classify the work when you have the signal.</p></div><span className="local-badge"><span className="live-dot" />Saved locally</span></div><div className="quick-capture-layout"><section className="panel capture-panel"><SectionHeader kicker="CAPTURE" title="A small brief that can grow" detail="Work Type and Effect Type stay separate so the collection remains useful at scale." /><div className="form-grid two"><Field label="Task name" required value={draft.name} onChange={(value) => patch('name', value)} placeholder="e.g. Portal activation pass" /><Field label="Work Type" value={draft.workType} onChange={(value) => patch('workType', value as WorkType)} options={WORK_TYPES} /><Field label="Effect Type" value={draft.effectType} onChange={(value) => patch('effectType', value as EffectType)} options={EFFECT_TYPES} /><Field label="Map or mode" value={draft.mapMode} onChange={(value) => patch('mapMode', value)} placeholder="Optional" /><Field label="Jira ID or link" value={draft.jira} onChange={(value) => patch('jira', value)} placeholder="Optional" /><Field label="Current status" value={draft.stage} onChange={(value) => patch('stage', value as Stage)} options={STAGES} /><Field label="Next action" value={draft.nextAction} onChange={(value) => patch('nextAction', value)} placeholder="Optional" /><Field label="Priority" value={draft.priority} onChange={(value) => patch('priority', value as Priority)} options={PRIORITIES} /></div><div className="field-block"><div className="field-label">Tags <span className="muted">optional</span></div><div className="chip-grid">{EFFECT_TAGS.map((tag) => <button type="button" key={tag} className={cn('select-chip', draft.tags.includes(tag) && 'selected')} onClick={() => toggleTag(tag)}>{draft.tags.includes(tag) && <Check size={12} />}{tag}</button>)}</div></div><Field label="Raw request or note" type="textarea" value={draft.rawRequest} onChange={(value) => patch('rawRequest', value)} placeholder={rawPlaceholder} /><div className="capture-actions"><button className="secondary-button" onClick={extract}><Sparkles size={14} />Extract suggestions</button><button className="primary-button" onClick={onCreate}><Plus size={15} />Save task</button></div>{suggestions.effectType || suggestions.workType || suggestions.mapMode || suggestions.discipline || suggestions.missing.length ? <div className="suggestion-box"><div className="suggestion-head"><div><span className="panel-kicker">LOCAL SUGGESTIONS</span><h3>Review before applying</h3></div><span className="soft-chip">No external AI</span></div><p className="muted-copy">Keyword matches stay local and never change the task until you apply them.</p><div className="suggestion-list">{suggestions.workType && <Suggestion label="Work type" value={suggestions.workType} onApply={() => patch('workType', suggestions.workType!)} />}{suggestions.effectType && <Suggestion label="Effect type" value={suggestions.effectType} onApply={() => patch('effectType', suggestions.effectType!)} />}{suggestions.mapMode && <Suggestion label="Map or mode" value={suggestions.mapMode} onApply={() => patch('mapMode', suggestions.mapMode!)} />}{suggestions.discipline && <Suggestion label="Requesting discipline" value={suggestions.discipline} onApply={() => patch('requestingDiscipline', suggestions.discipline!)} />}{suggestions.missing.map((item) => <div className="suggestion-missing" key={item}><ShieldAlert size={13} />Possible missing info: {item}</div>)}</div></div> : null}</section><aside className="capture-side"><section className="panel capture-side-card"><div className="panel-kicker">ADVANCED DETAILS</div><button className="details-toggle" onClick={() => setShowDetails(!showDetails)}><span>{showDetails ? 'Hide production details' : 'Add production details'}</span>{showDetails ? <ChevronDown size={15} /> : <ArrowRight size={15} />}</button>{showDetails && <div className="advanced-details"><Field label="Custom work type" value={draft.workType} onChange={(value) => patch('workType', value as WorkType)} placeholder="Optional custom category" /><Field label="Custom effect type" value={draft.effectType} onChange={(value) => patch('effectType', value as EffectType)} placeholder="Optional custom effect category" /><Field label="Feature name" value={draft.feature} onChange={(value) => patch('feature', value)} /><Field label="Request source" value={draft.source} onChange={(value) => patch('source', value)} /><Field label="Requesting discipline" value={draft.requestingDiscipline} onChange={(value) => patch('requestingDiscipline', value)} options={DISCIPLINES.filter((item) => item !== 'Nobody')} /><Field label="Requesting person" value={draft.requester} onChange={(value) => patch('requester', value)} /><Field label="Target date" type="date" value={draft.targetDate} onChange={(value) => patch('targetDate', value)} /></div>}</section><section className="panel capture-side-card clarification-card"><div className="panel-kicker">OPTIONAL CLARIFICATION</div><p className="muted-copy">Capture now; resolve unanswered questions later.</p><div className="message-preview">{selectedMissing.length ? `${selectedMissing.length} possible clarification item${selectedMissing.length === 1 ? '' : 's'} will stay visible.` : 'No missing information flags yet.'}</div><button className="secondary-button full-width" onClick={onCopy}><Copy size={14} />Copy note</button></section></aside></div></div>
}

